package main

import "fmt"

type Counter struct{ n int }

func (c Counter) Get() int { return c.n }
func (c *Counter) Inc()    { c.n++ }

type Incer interface{ Inc() }

func main() {
	c := Counter{}
	c.Inc() // Go takes &c for you
	fmt.Println(c.Get())

	var v any = c
	_, ok := v.(Incer)
	fmt.Println("Counter is Incer:", ok)

	var p any = &c
	_, ok = p.(Incer)
	fmt.Println("*Counter is Incer:", ok)
	p.(Incer).Inc()
	fmt.Println(c.Get())
}

