func reassign(p *int) {
	x := 100
	p = &x
}

func write(p *int) {
	*p = 100
}

func main() {
	n := 1
	p := &n
	reassign(p)
	fmt.Println(n, p == &n)
	write(p)
	fmt.Println(n)
}

package main

import "fmt"

type Point struct{ X, Y int }

func local() int {
	p := new(Point) // never leaves local
	p.X = 3
	return p.X
}

func leak() *Point {
	p := Point{X: 4} // its address outlives leak
	return &p
}

func main() {
	fmt.Println(local())
	q := leak()
	fmt.Println(q.X)
}

