func counter() func() int {
	n := 0
	return func() int {
		n++
		return n
	}
}

func main() {
	a := counter()
	b := counter()
	fmt.Println(a(), a(), a())
	fmt.Println(b())

	x := 1
	show := func() { fmt.Println("x is", x) }
	x = 2
	show()
