import "fmt"

func Sum[T ~int | ~float64](xs []T) T {
	var total T
	for _, x := range xs {
		total += x
	}
	return total
}

type Cents int

func main() {
	fmt.Println(Sum([]int{1, 2, 3}))
	fmt.Println(Sum([]float64{1.5, 2.25}))
	fmt.Println(Sum([]Cents{100, 250}))
}

package main

import (
	"errors"
	"fmt"
)

var ErrNotFound = errors.New("not found")

type QueryError struct{ Query string }

func (e *QueryError) Error() string { return "bad query " + e.Query }

func main() {
	err := fmt.Errorf("load user: %w", ErrNotFound)
	fmt.Println(err)
	fmt.Println(err == ErrNotFound, errors.Is(err, ErrNotFound))

	err = fmt.Errorf("handler: %w", &QueryError{Query: "id=7"})
	var qe *QueryError
	if errors.As(err, &qe) {
		fmt.Println("query was", qe.Query)
	}
}

