import "fmt"

func main() {
	ch := make(chan int)
	go func() {
		for i := 1; i <= 3; i++ {
			ch <- i
		}
		close(ch) // the sender closes
	}()
	for v := range ch {
		fmt.Println(v)
	}
	fmt.Println("range ended")
}

package main

import "fmt"

func main() {
	ch := make(chan int, 1)
	for i := 0; i < 3; i++ {
		select {
		case ch <- i:
			fmt.Println("sent", i)
		default:
			fmt.Println("full, dropped", i)
		}
	}
	for i := 0; i < 2; i++ {
		select {
		case v := <-ch:
			fmt.Println("got", v)
		default:
			fmt.Println("empty")
		}
	}
}

