package main

import "fmt"

func produce(ch chan<- int, vals ...int) {
	for _, v := range vals {
		ch <- v
	}
	close(ch)
}

func main() {
	a, b := make(chan int), make(chan int)
	go produce(a, 1, 2, 3)
	go produce(b, 10, 20)
	sum := 0
	for a != nil || b != nil {
		select {
		case v, ok := <-a:
			if !ok {
				a = nil
				continue
			}
			sum += v
		case v, ok := <-b:
			if !ok {
				b = nil
				continue
			}
			sum += v
		}
	}
	fmt.Println("sum:", sum)
}

